import {musicStyle} from './music-styles.js';
import {composeSong,songStructureFields,readSongStructure} from './music-song.js';
import {arrangeSections,applyChordRoots,filterMusicSamples} from './music-arrange.js';
import {MUSIC_KEYS,MUSIC_SCALES,MUSIC_MOODS,MUSIC_GENRES,readMIDI,composeMusic,compileMusic,availableVoices,checkScore,writeMIDI,remixMusic} from './music-compose.js';

export function musicComposer(api){
 const $=s=>document.querySelector(s),esc=api.esc;
 function open(imported=null){
  let score=imported?.score||composeSong(),candidate=null;const sections=imported&&score.length>512*96?[{from:1,to:512,repeat:1,transpose:0,gain:100}]:[];const partRows=structuredClone(score.tracks),enabled=partRows.map(()=>true);
  const sources=api.tracks(),options=(items,current)=>items.map(([value,label])=>`<option value="${esc(String(value))}" ${String(current)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
  api.modal(imported?'Arrange music':'Compose music',`${!imported&&api.quick?'<button id="composeQuick" class="primary" type="button">Quick Track · configure from a vibe</button>':''}<p>${imported?'Choose the parts to include, or solo one part. Imports retain every part. Matching instruments can share export tracks without changing notes. Mute or solo parts to meet the export limits, then map instruments and save.':'Build a full song with an optional intro, repeating groove and developing melodic bridge. Scene styles and genres choose phrase rhythms, bass movement, accompaniment, percussion and melodic shape. Each seed develops a different hook and harmonic route. The same settings and seed reproduce the same song.'}</p>${!imported&&sources.length?`<fieldset><legend>Compose from a reference</legend><label>Source song<select id="composeReference"><option value="">Choose one library song</option>${sources.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></label><button id="composeUseReference" type="button">Choose part & compose</button><p>Only the selected song is used. An additional reference can be chosen on the next screen.</p></fieldset>`:''}<label>Track name<input id="composeName" maxlength="120" value="${esc(imported?.name||'Battle variation')}"></label>${imported?'':`<div class="studio-grid"><label>Scene style<select id="composeMood">${options(Object.keys(MUSIC_MOODS).map(s=>[s,s]),'Battle')}</select></label><label>Genre<select id="composeGenre">${options(Object.keys(MUSIC_GENRES).map(v=>[v,v]),'Game soundtrack')}</select></label><label>Key<select id="composeKey">${options(MUSIC_KEYS.map((s,i)=>[i,s]),0)}</select></label><label>Scale<select id="composeScale">${options(Object.keys(MUSIC_SCALES).map(s=>[s,s]),'Natural minor')}</select></label><label>Tempo (BPM)<input id="composeTempo" type="number" min="10" max="510" step="2" value="168"></label><label>Variation seed<input id="composeSeed" type="number" min="0" max="4294967295" value="1"></label><label>Complexity <output id="complexityValue">45</output><input id="composeComplexity" type="range" min="0" max="100" value="45"></label><label>Experimentation <output id="adventureValue">15</output><input id="composeAdventure" type="range" min="0" max="100" value="15"></label></div>`}${!imported?'<p id="composeStyleDescription" class="callout"></p>'+songStructureFields('compose'):''}<label>Instrument source<select id="composeBank"><option value="">Original chip instruments</option>${imported?.bankAsset?'<option value="__attached">Attached Quick Track instrument bank</option>':''}${sources.map(t=>`<option value="${esc(t.id)}">${esc(t.name)} — instruments</option>`).join('')}</select></label><div id="composeParts"></div><details ${sections.length?'open':''}><summary>Sections & chord roots</summary><p>Copy bar ranges into a new order. Notes crossing a section boundary are trimmed. ${imported?'Source: '+Math.ceil(imported.score.length/96)+' bars. Export up to 512 bars at a time.':''}</p><div id="composeSectionRows"></div><button id="composeSectionAdd" type="button">＋ Add section</button><label><input id="composeChordsEnabled" type="checkbox"> Move bass and harmony to chord roots</label><label>Scale degrees (1–7, comma separated)<input id="composeChords" value="1,4,5,1"></label><label>Bars per chord<input id="composeChordBars" type="number" min="1" max="16" value="1"></label><p class="hint-line">Chord roots apply to parts 2 and 3 and retain each phrase’s intervals. Percussion stays unchanged.</p></details><label><input id="composeLoop" type="checkbox" ${imported?.loop===false?'':'checked'}> Loop in game</label><label>Loop starts at bar<input id="composeLoopStart" type="number" min="1" max="512" step="any" value="${1+(score.loopStart||0)/96}"></label><p class="hint-line">Everything before this bar plays once. The remaining bars repeat.</p><p id="composeReport" class="studio-status"></p>${imported?.warnings?.length?`<p class="hint-line">${imported.warnings.map(esc).join('<br>')}</p>`:''}<div class="studio-actions"><button id="composePreview" type="button">▶ Preview</button><button id="composeMIDI" type="button">Export MIDI</button><button id="composeEditNotes" type="button">Edit notes & motifs</button>${imported?'':'<button id="composeVariation" type="button">Next variation</button>'}<button id="composeStop" type="button">■ Stop preview</button></div><p class="hint-line">${imported?'Source instruments are replaced by your choices above.':'Phrase composition runs offline, using an aggregate rhythm and interval vocabulary from full-length source songs. Use Notes & motifs on a library track for reference-guided composition.'} Up to eight simultaneous notes. ROM export uses the verified music adapters; preview effects are approximate.</p>`,()=>{const asset=build();api.add(asset);api.openLibrary();api.toast('Track saved. Assign it to a map or scene to include it in the ROM.');},'Add to library');
  if($('#composeQuick'))$('#composeQuick').onclick=()=>{api.stop();api.quick();};
  const drawSections=()=>{$('#composeSectionRows').innerHTML=sections.map((s,i)=>`<fieldset><legend>Section ${i+1}</legend>${[['from','First bar',1,2048],['to','Last bar',1,2048],['repeat','Repeats',1,16],['transpose','Semitones',-24,24],['gain','Volume %',1,150]].map(([key,label,min,max])=>`<label>${label}<input type="number" data-section="${i}" data-section-key="${key}" min="${min}" max="${max}" value="${s[key]}"></label>`).join('')}<button data-section-up="${i}" type="button" ${i?'':'disabled'}>Move up</button><button data-section-remove="${i}" type="button">Remove</button></fieldset>`).join('');document.querySelectorAll('[data-section]').forEach(el=>el.onchange=()=>sections[+el.dataset.section][el.dataset.sectionKey]=+el.value);document.querySelectorAll('[data-section-up]').forEach(el=>el.onclick=()=>{const i=+el.dataset.sectionUp;[sections[i-1],sections[i]]=[sections[i],sections[i-1]];drawSections();});document.querySelectorAll('[data-section-remove]').forEach(el=>el.onclick=()=>{sections.splice(+el.dataset.sectionRemove,1);drawSections();});};$('#composeSectionAdd').onclick=()=>{if(sections.length>=32){api.error(Error('Use up to 32 sections.'));return;}sections.push({from:1,to:Math.ceil((imported?.score.length||Object.values(readSongStructure('compose')).reduce((a,b)=>a+b,0)*96)/96),repeat:1,transpose:0,gain:100});drawSections();};
  const bank=()=>$('#composeBank').value==='__attached'?imported?.bankAsset||null:sources.find(t=>t.id===$('#composeBank').value)?.asset||null;
  const drawParts=()=>{const voices=availableVoices(bank());$('#composeParts').innerHTML=voices.length?partRows.map((t,i)=>`<label><input data-compose-enabled="${i}" type="checkbox" ${enabled[i]?'checked':''}> Include ${esc(t.name||'Part '+(i+1))}</label><button type="button" data-compose-solo="${i}">Solo this part</button><label>${esc(t.name||'Part '+(i+1))} instrument<select data-compose-part="${i}">${options(voices.map(v=>[v.program,v.name]),voices.some(v=>v.program===t.program)?t.program:voices[i%voices.length].program)}</select></label>`).join(''):'<p>No supported instruments in this track. Choose another source or the original chip instruments.</p>';document.querySelectorAll('[data-compose-enabled]').forEach(c=>c.onchange=()=>enabled[+c.dataset.composeEnabled]=c.checked);document.querySelectorAll('[data-compose-solo]').forEach(b=>b.onclick=()=>{enabled.fill(false);enabled[+b.dataset.composeSolo]=true;document.querySelectorAll('[data-compose-enabled]').forEach(c=>c.checked=enabled[+c.dataset.composeEnabled]);candidate=null;});candidate=null;};
  function buildScore(){if(!imported)score=composeSong({...readSongStructure('compose'),mood:$('#composeMood').value,genre:$('#composeGenre').value,key:+$('#composeKey').value,scale:$('#composeScale').value,tempo:+$('#composeTempo').value,complexity:+$('#composeComplexity').value,adventure:+$('#composeAdventure').value,seed:+$('#composeSeed').value});else score=structuredClone(imported.score);document.querySelectorAll('[data-compose-part]').forEach(s=>score.tracks[+s.dataset.composePart].program=+s.value);if(sections.length)score=arrangeSections(score,sections.map(s=>({from:(s.from-1)*96,to:Math.min(s.to*96,score.length),repeat:s.repeat,transpose:s.transpose,gain:s.gain})));if($('#composeChordsEnabled').checked)score=applyChordRoots(score,{key:imported?0:+$('#composeKey').value,scale:imported?'Major':$('#composeScale').value,degrees:$('#composeChords').value.split(',').map(n=>Number(n.trim())-1),parts:[1,2].filter(i=>score.tracks[i]),barsPerChord:+$('#composeChordBars').value});score.loopStart=Math.round((+$('#composeLoopStart').value-1)*96);score.tracks=score.tracks.filter((t,i)=>enabled[i]);checkScore(score,{arranging:true});return score;}
  function build(){if(!availableVoices(bank()).length)throw Error('Choose an instrument source with playable voices.');buildScore();candidate=compileMusic(score,{bankAsset:bank(),loop:$('#composeLoop').checked,name:$('#composeName').value.trim()||'New track'});const stats=checkScore(candidate.arrangement.score);$('#composeReport').textContent=`${score.tracks.length} source parts → ${stats.parts} export parts · ${stats.notes} notes · peak ${stats.peak} voices · ${(candidate.sourceBytes/1024).toFixed(1)} KB including instruments`;return candidate;}
  const safely=fn=>async()=>{try{await fn();}catch(e){api.error(e);}};
  if(imported?.bankAsset)$('#composeBank').value='__attached';else if(imported?.bankId&&sources.some(t=>t.id===imported.bankId&&availableVoices(t.asset).length))$('#composeBank').value=imported.bankId;$('#composeBank').onchange=drawParts;drawParts();drawSections();if($('#composeUseReference'))$('#composeUseReference').onclick=()=>{try{const t=sources.find(t=>t.id===$('#composeReference').value);if(!t)throw Error('Choose a source song first.');api.stop();api.generateReference(t);}catch(e){api.error(e);}};try{build();}catch(error){$('#composeReport').textContent=error.message;}$('#composePreview').onclick=safely(()=>api.play(build()));$('#composeStop').onclick=api.stop;$('#composeEditNotes').onclick=safely(()=>api.editScore(buildScore(),$('#composeName').value.trim()||'New track',{bankAsset:bank(),bankId:$('#composeBank').value||null,loop:$('#composeLoop').checked}));$('#composeMIDI').onclick=safely(()=>{build();return api.save(new Blob([writeMIDI(score)],{type:'audio/midi'}),filename()+'.mid');});
  const filename=()=>($('#composeName').value.trim()||'New_track').replace(/[^a-z0-9]+/gi,'_');
  if(!imported){const describe=()=>$('#composeStyleDescription').textContent=musicStyle($('#composeMood').value,$('#composeGenre').value).description;const styleParts=()=>{const generated=composeSong({mood:$('#composeMood').value,genre:$('#composeGenre').value});partRows.forEach((t,i)=>t.program=generated.tracks[i].program);drawParts();describe();try{build();}catch(e){$('#composeReport').textContent=e.message;}};$('#composeGenre').onchange=styleParts;describe();const describeStructure=()=>{const v=readSongStructure('compose');$('#composeLoopStart').value=v.introBars+1;$('#composestructureSummary').textContent=`${v.introBars+v.verseBars+v.bridgeBars} bars · loop starts at bar ${v.introBars+1}`;};for(const key of ['introBars','verseBars','bridgeBars'])$('#compose'+key).oninput=describeStructure;describeStructure();$('#composeMood').onchange=()=>{const mood=$('#composeMood').value,p=MUSIC_MOODS[mood];$('#composeTempo').value=p.tempo;$('#composeScale').value=p.scale;$('#composeName').value=mood+' theme';styleParts();};$('#composeVariation').onclick=safely(()=>{$('#composeSeed').value=(+$('#composeSeed').value+1)>>>0;return api.play(build());});for(const [id,out]of [['composeComplexity','complexityValue'],['composeAdventure','adventureValue']])$('#'+id).oninput=()=>$('#'+out).textContent=$('#'+id).value;}
 }
 async function importFile(file){if(!file)return;if(file.size>2*1024*1024)throw Error('Use a MIDI file under 2 MB.');open({...readMIDI(new Uint8Array(await file.arrayBuffer())),name:file.name.replace(/\.(?:midi?|rmi)$/i,'')});}
 function remix(t){api.modal('Variation · '+t.name,`<p>Keep the exact notes, instruments and loop structure while changing speed and level. Save as a separate track.</p><label>Name<input id="remixName" maxlength="120" value="${esc(t.name+' variation')}"></label><label>Tempo (%)<input id="remixTempo" type="number" min="25" max="200" value="100"></label><label>Volume (%)<input id="remixVolume" type="number" min="0" max="150" value="100"></label><details><summary>PCM sample filters</summary><label>Low-pass openness (%)<input id="remixLowpass" type="number" min="1" max="100" value="100"></label><label>High-pass amount (%)<input id="remixHighpass" type="number" min="0" max="100" value="0"></label><label>Drive (%)<input id="remixDrive" type="number" min="0" max="100" value="0"></label><label>Bit depth<input id="remixBits" type="number" min="2" max="8" value="8"></label><p>Filters affect PCM instruments shared within this new track. PSG instruments retain their native sound.</p></details><div class="studio-actions"><button id="remixOriginal" type="button">▶ Original</button><button id="remixPreview" type="button">▶ Variation</button><button id="remixStop" type="button">Stop</button></div>`,()=>{api.add(build());api.openLibrary();api.toast('Variation saved as a separate track.');},'Add variation');const build=()=>{let asset=remixMusic(t.asset,{name:$('#remixName').value.trim()||t.name+' variation',tempo:+$('#remixTempo').value,volume:+$('#remixVolume').value});const settings={lowpass:+$('#remixLowpass').value,highpass:+$('#remixHighpass').value,drive:+$('#remixDrive').value,bitDepth:+$('#remixBits').value,name:asset.name};if(settings.lowpass!==100||settings.highpass||settings.drive||settings.bitDepth!==8)asset=filterMusicSamples(asset,settings);return asset;};$('#remixOriginal').onclick=()=>api.play(t.asset).catch(api.error);$('#remixPreview').onclick=()=>{try{api.play(build()).catch(api.error);}catch(e){api.error(e);}};$('#remixStop').onclick=api.stop;}
 return{open,importFile,remix};
}
